#!/usr/bin/env python3
from __future__ import annotations
import base64,json,re,sys,zlib
from pathlib import Path
MARKER='GM_BOS_FV3_UX_PRINTSPELL_PAGE100_V37'
PAYLOAD=''

def outer(text):
 for marker in ("function __gmLazyScribeSrc(){return ","PAGES.scribe = "):
  if marker in text:
   pos=text.index(marker)+len(marker); page,n=json.JSONDecoder().raw_decode(text[pos:]); return pos,page,n
 raise SystemExit('Scribe source not found')

def main():
 if len(sys.argv)!=3: raise SystemExit('usage: patch_v37_bos_ux_printspell_page100.py INPUT.html OUTPUT.html')
 src,dst=map(Path,sys.argv[1:]); text=src.read_text(encoding='utf-8'); pos,page,n=outer(text)
 if MARKER in page: raise SystemExit('V37 already applied')
 pairs=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
 for old,new,label in pairs:
  count=page.count(old)
  if count!=1: raise SystemExit(f'{label}: expected 1 match, found {count}')
  page=page.replace(old,new,1)
 for nav in ('gmBosPrev','gmBosNext','gmBosBack','gmBosChapterContentsBtn','gmBosContentsBtn','gmBosBindBookBtn'):
  count=page.count('id="'+nav+'"')
  if count!=1: raise SystemExit(f'navigation {nav} count changed: {count}')
 for token in (MARKER,'>Print Spell</button>','id="gmInkPrintSpellBtn"','function printSpell(options)','spellCatalog:gmBosSpellCatalog','const packs=chunk(rows,18)','function gmBosCaptureRenderable(node,root)','imageSkipped:allImgs.length-imgs.length',"pages.forEach(p=>{if(p.dataset.chapter==='cover')",'artRasterCache:new Map()'):
  if token not in page: raise SystemExit('missing V37 requirement: '+token)
 if 'Read Symbols</b>' in page: raise SystemExit('old Read Symbols panel remains')
 if page.count(r"!/^data:image\//i.test(String(url||''))")!=1: raise SystemExit('V36 artwork-cache repair missing or duplicated')
 enc=json.dumps(page,ensure_ascii=False,separators=(',',':'));enc=re.sub(r'</script',r'<\\/script',enc,flags=re.I)
 dst.write_text(text[:pos]+enc+text[pos+n:],encoding='utf-8')
 print('V37 BoS UX + Print Spell + Contents numbering + page-100 capture patch passed.')
if __name__=='__main__':main()
